-- Create table
-- Sa PostgreSQL, gumamit ng double quote para ma-preserve
-- ang capitalization ng table at column names.
-- Kapag walang double quote, automatic itong nagiging lowercase.
CREATE TABLE IF NOT EXISTS "tblExpense" (
    "ExpenseID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Ice" INT,
    "Water" INT,
    "Electricity" INT,
    "Rent" INT,
    "RawMats" INT,
    "Others" INT,
    "Others_Desc" TEXT,
    "Salary1" INT,
    "Salary2" INT,
    "Quantity" DECIMAL(10,0),
    "DateAdded" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    "CreatedBy" UUID
        REFERENCES auth.users(id)
        ON DELETE CASCADE
);


-- CREATE INDEX

CREATE INDEX IF NOT EXISTS "idx_tblExpense_ExpenseID"
ON "tblExpense" ("ExpenseID");
CREATE INDEX IF NOT EXISTS "idx_tblExpense_ExpenseID"
ON "tblExpense" ("ExpenseID");
 

-- Enable Row Level Security (RLS)

-- Makaka-edit/delete lang ng item
-- kung kanino naka-assign

ALTER TABLE "tblExpense"
ENABLE ROW LEVEL SECURITY;


-- Policy: Users can view all Expense

CREATE POLICY "User can view all Expense"

ON "tblExpense"

FOR SELECT

USING (true);


-- Policy: Users can create Expense

CREATE POLICY "User can create Expense"

ON "tblExpense"

FOR INSERT

WITH CHECK (auth.uid() = "CreatedBy");


-- Policy: User can update Expense
-- that they created or assigned

CREATE POLICY "User can update Expense that they created or assigned"

ON "tblExpense"

FOR UPDATE

USING (
    auth.uid() = "CreatedBy"
)

WITH CHECK (
    auth.uid() = "CreatedBy"
);


-- Policy: Only creators can delete Expense

CREATE POLICY "Only creators can delete Expense"

ON "tblExpense"

FOR DELETE

USING (auth.uid() = "CreatedBy");


-- Function to update timestamp

CREATE OR REPLACE FUNCTION update_DateAdded()

RETURNS TRIGGER AS $$

BEGIN

    NEW."DateAdded" = NOW();

    RETURN NEW;

END;

$$ LANGUAGE plpgsql;


-- Trigger

CREATE TRIGGER update_tblExpense_DateAdded

BEFORE UPDATE ON "tblExpense"

FOR EACH ROW

EXECUTE FUNCTION update_DateAdded();